/* eslint-disable */
/**
 * sync-smartico-lib.js — regenerate `src/SmarticoLib/index.ts` from the tracker.
 *
 * `SmarticoLib` holds the type declarations of the tracker's `_smartico` object
 * (`Smartico.ts`): the `EXTERNAL_CALLBACK_KEY` enum (the `_smartico.on` events),
 * deep links, widget params, `PublicProperties`, … It is generated by
 * dts-bundle-generator from `../tracker/src/tracker/Smartico.ts`, using the
 * tracker's own node_modules.
 *
 * public-api types are kept EXTERNAL (not inlined): inlining would copy this
 * package's own types back in from the tracker's older installed version. The
 * generated imports are rewritten to this repo's own source, and the file
 * re-exports this package's root types, so old imports from
 * `@smartico/public-api/dist/SmarticoLib` (tracker `Banners.ts`:
 * ProtocolMessage / ProtocolResponse; r-games-client: DeepLink) keep working.
 * Only `dist/SmarticoLib/index.d.ts` ships — no runtime code.
 *
 *   node scripts/sync-smartico-lib.js     (npm run sync-smartico-lib)
 *
 * Fails loudly when the tracker is missing, the generator fails, or the output
 * has an import this script does not know how to rewrite.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const TRACKER = path.resolve(ROOT, '..', 'tracker');
const ENTRY = 'src/tracker/Smartico.ts';
const OUT = path.join(ROOT, 'src', 'SmarticoLib', 'index.ts');

// generated import source → this repo's source (relative to src/SmarticoLib/)
const IMPORT_MAP = {
	'@smartico/public-api': '../index',
	'@smartico/public-api/dist/WSAPI/WSAPI': '../WSAPI/WSAPI',
};

function fail(msg) {
	console.error(`sync-smartico-lib: ${msg}`);
	process.exit(1);
}

if (!fs.existsSync(path.join(TRACKER, ENTRY))) fail(`tracker entry not found: ${path.join(TRACKER, ENTRY)}`);
const bin = path.join(TRACKER, 'node_modules', '.bin', 'dts-bundle-generator');
if (!fs.existsSync(bin)) fail(`dts-bundle-generator not installed in the tracker (${bin}) — run npm install in ../tracker`);

const tmp = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'smartico-lib-')), 'index.ts');
try {
	// --no-check: the output's imports only resolve after the rewrite below; tsc checks it afterwards
	execFileSync(bin, ['--no-check', '-o', tmp, ENTRY], { cwd: TRACKER, stdio: ['ignore', 'pipe', 'inherit'] });
} catch (e) {
	fail(`dts-bundle-generator failed (exit ${e.status})`);
}

let src = fs.readFileSync(tmp, 'utf8');
const unknown = [];
src = src.replace(/^(import [^;]+ from )(['"])([^'"]+)\2;/gm, (line, head, _q, from) => {
	if (!(from in IMPORT_MAP)) {
		unknown.push(from);
		return line;
	}
	return `${head}'${IMPORT_MAP[from]}';`;
});
if (unknown.length) fail(`unknown import(s) in generated output — add them to IMPORT_MAP: ${unknown.join(', ')}`);

const trackerCommit = execFileSync('git', ['-C', TRACKER, 'log', '-1', '--format=%h %ad', '--date=short'], { encoding: 'utf8' }).trim();
const header = [
	'// Generated by scripts/sync-smartico-lib.js from the tracker (src/tracker/Smartico.ts',
	`// at ${trackerCommit}). Do NOT edit by hand — fix the tracker source and re-run the script.`,
	'',
].join('\n');
const compat = [
	'',
	"// This package's own types, so imports from '@smartico/public-api/dist/SmarticoLib' keep working.",
	"export * from '../index';",
	// exported by the old hand-kept copy but not from the package root
	"export type { ProtocolMessage } from '../Base/ProtocolMessage';",
	"export type { ProtocolResponse } from '../Base/ProtocolResponse';",
	"export type { GetAchievementsUserInfoResponse } from '../Core/GetAchievementsUserInfoResponse';",
	'',
].join('\n');

fs.writeFileSync(OUT, header + src.replace(/^\/\/ Generated by dts-bundle-generator[^\n]*\n/, '').trimEnd() + '\n' + compat);
console.log(`sync-smartico-lib: wrote ${path.relative(ROOT, OUT)} (${src.split('\n').length} lines, tracker ${trackerCommit})`);
